def build_metric_payload(
    key: str,
    values_by_field: dict[str, dict[date, float]],
    failed_sources: dict[str, str],
    start_date: date,
    end_date: date,
    native_hrv_payload: object | None = None,
) -> dict[str, Any]:
    """Build one UI-safe metric record from normalized dated measurements."""
    source_key = METRIC_SOURCES[key]
    spec = METRICS[source_key]
    selected = _select_series(values_by_field, spec)
    metric: dict[str, Any] = {
        "label": "Resting heart rate" if key == "restingHeartRate" else spec.label,
        "unit": spec.unit,
        "field": None,
        "points": [],
        "latest": None,
        "baseline7": None,
        "baseline28": None,
        "usualRange28": None,
        "rangeLabel": "Prior 28-day personal range",
        "garminStatus": None,
        "status": "unavailable",
        "availableDays": 0,
        "unavailableReason": None,
    }

    if selected is None:
        if source_key in failed_sources:
            metric["unavailableReason"] = "Garmin could not return this data right now."
        else:
            metric["unavailableReason"] = "No matching measurements were returned for this period."
        return metric

    field, source_values = selected
    readings = sorted(
        (reading_date, value)
        for reading_date, value in source_values.items()
        if start_date <= reading_date <= end_date
    )
    if not readings:
        metric["unavailableReason"] = "No dated measurements were returned for this period."
        return metric

    points = []
    for reading_date, value in readings:
        display_value, unit = _format_value(value, field, spec)
        points.append({"date": reading_date.isoformat(), "value": round(display_value, 2)})

    metric["field"] = field
    metric["unit"] = "score" if source_key == "stress" else unit
    metric["points"] = points
    metric["latest"] = points[-1]
    metric["availableDays"] = len(points)

    latest_date = readings[-1][0]
    baseline_end = latest_date - timedelta(days=1)
    baseline_start = baseline_end - timedelta(days=27)
    baseline_readings = [
        (reading_date, value)
        for reading_date, value in readings
        if baseline_start <= reading_date <= baseline_end
    ]
    week_start = latest_date - timedelta(days=7)
    recent_week = [value for reading_date, value in readings if week_start <= reading_date < latest_date]

    if len(recent_week) >= 4:
        metric["baseline7"] = round(mean(_display_values(recent_week, field, spec)), 2)
    if len(baseline_readings) >= MINIMUM_BASELINE_DAYS:
        baseline_values = _display_values([value for _, value in baseline_readings], field, spec)
        range_low = _percentile(baseline_values, 0.1)
        range_high = _percentile(baseline_values, 0.9)
        latest_value = points[-1]["value"]
        metric["baseline28"] = round(median(baseline_values), 2)
        metric["usualRange28"] = [round(range_low, 2), round(range_high, 2)]
        if latest_value < range_low:
            metric["status"] = "below_usual"
        elif latest_value > range_high:
            metric["status"] = "above_usual"
        else:
            metric["status"] = "within_usual"
    else:
        metric["status"] = "insufficient_history"

    if key == "hrv":
        native_baseline = _find_native_hrv_baseline(native_hrv_payload, latest_date)
        if native_baseline is not None:
            balanced_low, balanced_upper, garmin_status = native_baseline
            metric["usualRange28"] = [balanced_low, balanced_upper]
            metric["rangeLabel"] = "Garmin balanced range"
            metric["garminStatus"] = garmin_status
            latest_value = points[-1]["value"]
            if latest_value < balanced_low:
                metric["status"] = "below_usual"
            elif latest_value > balanced_upper:
                metric["status"] = "above_usual"
            else:
                metric["status"] = "within_usual"

    return metric


def _find_native_hrv_baseline(
    payload: object | None,
    target_date: date,
) -> tuple[float, float, str | None] | None:
    """Read Garmin's HRV balanced bounds for the latest date when present."""
    if not isinstance(payload, dict):
        return None
    summaries = payload.get("hrvSummaries")
    if not isinstance(summaries, list):
        return None
    for summary in summaries:
        if not isinstance(summary, dict) or summary.get("calendarDate") != target_date.isoformat():
            continue
        baseline = summary.get("baseline")
        if not isinstance(baseline, dict):
            return None
        low = baseline.get("balancedLow")
        high = baseline.get("balancedUpper")
        if isinstance(low, (int, float)) and isinstance(high, (int, float)):
            status = summary.get("status")
            return float(low), float(high), status if isinstance(status, str) else None
    return None


def _display_values(values: list[float], field: str, spec: Any) -> list[float]:
    """Convert a sequence using the same unit conversion as individual readings."""
    return [_format_value(value, field, spec)[0] for value in values]


def _percentile(values: list[float], fraction: float) -> float:
    """Linearly interpolate a percentile from an ordered sample."""
    ordered = sorted(values)
    position = (len(ordered) - 1) * fraction
    lower_index = int(position)
    upper_index = min(lower_index + 1, len(ordered) - 1)
    weight = position - lower_index
    return ordered[lower_index] * (1 - weight) + ordered[upper_index] * weight


def build_training_briefing(
    metrics: dict[str, dict[str, Any]],
    training_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Create a conservative training approach from deviations versus prior personal ranges."""
    recovery_metrics = {key: metrics[key] for key in WATCH_DIRECTIONS if key in metrics}
    ready_metrics = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] in {"within_usual", "below_usual", "above_usual"}
    ]
    outside_range = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] in {"below_usual", "above_usual"}
    ]
    flags = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] == f"{WATCH_DIRECTIONS[key]}_usual"
    ]
    # Generated by GitHub Copilot - Oct-24-2026
    ready_groups = {"sleep" if key == "sleepScore" else key for key in ready_metrics}
    caution_groups = {"sleep" if key == "sleepScore" else key for key in flags}
    volume_flag = bool(training_context and training_context.get("volumeStatus") == "well_above_recent")
    evidence = [
        {
            "metric": recovery_metrics[key]["label"],
            "direction": "below" if recovery_metrics[key]["status"] == "below_usual" else "above",
            "isCaution": key in flags,
            "usualRange": recovery_metrics[key]["usualRange28"],
            "unit": recovery_metrics[key]["unit"],
        }
        for key in outside_range
    ]
    if volume_flag:
        evidence.append({
            "metric": "Weekly activity duration",
            "direction": "above",
            "isCaution": True,
            "usualRange": None,
            "unit": "minutes",
        })
    if len(ready_groups) < 2:
        return {
            "approach": "Not enough recent history for a personalized suggestion.",
            "explanation": "There isn’t enough history to compare yet. Use how you feel today; a single reading cannot decide a workout.",
            "dataSufficiency": "Limited history",
            "evidence": evidence,
            "medicalDisclaimer": "This is general training context, not medical advice.",
        }

    if len(caution_groups) + int(volume_flag) >= 2:
        approach = "Consider rest or an easy session today."
        explanation = "Several recovery or training-volume signals differ from your usual pattern. An easier session is a cautious option, not a diagnosis; if you feel unwell, rest and seek appropriate care."
    elif len(caution_groups) == 1:
        approach = "Keep today flexible."
        explanation = f"{recovery_metrics[flags[0]]['label']} differs from your usual pattern. One signal alone doesn’t mean you must skip training; adjust intensity to how you feel."
    elif volume_flag:
        approach = "Consider an easy session or rest today."
        explanation = "Your recent training volume was much higher than usual. An easy session may help keep the day manageable, especially if you feel fatigued."
    elif outside_range:
        approach = "No training caution flagged."
        explanation = "Some measurements differ from your usual range, but a difference isn’t automatically a problem and doesn’t change today’s suggestion."
    else:
        approach = "Your recovery looks close to usual."
        explanation = "These readings are close to your recent personal ranges, not population scores. If you feel well, your planned session may be reasonable."

    return {
        "approach": approach,
        "explanation": explanation,
        "dataSufficiency": "Based on your recent personal ranges",
        "evidence": evidence,
        "medicalDisclaimer": "This is general training context, not medical advice.",
    }


