def main() -> int:
    """Fetch dashboard data and write one JSON document to standard output."""
    logging.basicConfig(format="%(levelname)s %(message)s")
    LOGGER.setLevel(logging.INFO)
    parser = argparse.ArgumentParser(description="Fetch personal Garmin health metrics as JSON.")
    parser.add_argument("--days", type=int, default=30)
    args = parser.parse_args()
    try:
        payload = fetch_dashboard_data(args.days)
    except Exception as error:
        print(f"Could not load Garmin health data ({type(error).__name__}).", file=sys.stderr)
        return 1
    json.dump(payload, sys.stdout, separators=(",", ":"))
    print()
    return 0


